/**
 * Soundtrack Match ("Pick the music"), part 2: the curated song catalog (schema and checks).
 *
 * The catalog is data, not code: `src/content/soundtrack/catalog.json`, generated by
 * `scripts/build-soundtrack-catalog.ts` from the owner-approved selection (soundtrack spec §5.2,
 * §12). Only metadata and YouTube video ids: no audio, no lyrics, no cover art, no Spotify ids.
 * The app loads it lazily (`src/client/data/soundtrack-catalog.ts`), so the start bundle stays
 * the same.
 *
 * Pure: no I/O, no clock, no randomness.
 */
import { z } from 'zod';
import { BPM_MAX, BPM_MIN } from './bpm-match';
import { YOUTUBE_ID, type QueueItem, type YoutubeCandidate } from './experience';
import { songKey } from './slot-plan';
import { MUSIC_CATEGORIES, type MusicCategoryId } from './soundtrack';

/**
 * What a song is for in a ride. `climb` = slow, heavy cadence (seated or standing climbs);
 * `intervals` = sprints and hard intervals. A song may have several.
 */
export const TRACK_ROLES = [
  'warmup',
  'steady',
  'climb',
  'intervals',
  'cooldown',
  'finisher',
] as const;
export type TrackRole = (typeof TRACK_ROLES)[number];

/**
 * `finisher` is a mark on top of the other roles (the song also has one of them): the last part of
 * a ride, high energy and a euphoric mood (energy-matching spec, section 8). The planner does not
 * read it yet.
 */
export const FINISHER_ROLE: TrackRole = 'finisher';

/**
 * The feel of a song, apart from its energy (spec section 8): the finisher is the euphoric ones.
 * Heard by ear, one per song.
 */
export const TRACK_MOODS = ['mellow', 'warm', 'euphoric', 'dark', 'aggressive', 'playful'] as const;
export type TrackMood = (typeof TRACK_MOODS)[number];

/** How steady the beat is to hold a cadence to: 1 loose or syncopated, 3 locked (spec section 8). */
export type TrackGroove = 1 | 2 | 3;

/**
 * `fallback` = a long, calm instrumental the ride may play wherever the songs leave silence (gap
 * rule R4, soundtrack spec §12): one or two in the catalog.
 */
export const TRACK_TRAITS = ['instrumental', 'loopable', 'long-intro', 'fallback'] as const;
export type TrackTrait = (typeof TRACK_TRAITS)[number];

export type TrackEnergy = 1 | 2 | 3 | 4 | 5;

/** One song of the catalog. Its YouTube uploads form the chain the player walks (main first). */
export interface CatalogTrack extends QueueItem {
  /** Stable slug, e.g. "kavinsky-nightcall"; a saved plan refers to it. */
  id: string;
  /**
   * Felt tempo (verified with two sources, octave folded to the one heard). Required for a song on
   * the beat; absent for a song without a clear beat (`beat: 'none'`).
   */
  bpm?: number;
  /** Length of the preferred version, seconds. */
  durationSec: number;
  /** At least two uploads, main first, each with its own length. */
  youtube: YoutubeCandidate[];
  /** Taste labels (at least one). */
  categories: MusicCategoryId[];
  /** What the song suits in a ride (at least one); see `ROLE_SPRINT_RPM`. */
  roles: TrackRole[];
  /**
   * How the song sounds, 1 = ambient or lo-fi, 5 = peak (heavy, aggressive, a drop). Heard by ear,
   * independent of the BPM and of the tempo the song is ridden at (energy-matching spec, section 2).
   */
  energy: TrackEnergy;
  /**
   * Predictability of the beat, 1 = loose, shifting or syncopated, 3 = locked and even; a
   * tie-breaker for steady parts and climbs. Absent for a song without a beat.
   */
  groove?: TrackGroove;
  /** The feel of the song; `finisher` songs are `euphoric`. */
  mood?: TrackMood;
  /** Revision of the energy tagging this song went through (absent = the first, rough one). */
  tagged?: 2;
  /**
   * One sentence on the energy, for the spot check: a doubt, a big change, or a conflict with the
   * song's role (e.g. a calm ballad that is ridden at 105 rpm and so is an intervals song).
   */
  energyNote?: string;
  /** 'none' = no clear beat (cool-down); there is no tempo to compare. */
  beat: 'steady' | 'none';
  /** False = explicit lyrics in the listed version. */
  clean: boolean;
  traits?: TrackTrait[];
  /** Why the tempo is what it is, e.g. "sources say 176 (octave)". */
  bpmNote?: string;
  /** A lesser-known pick ("gem") the owner wanted next to the hits. */
  gem?: true;
  /** A Polish artist (Polish songs are a fixed part of the mix, owner's rule). */
  pl?: true;
  /**
   * An add-on style (synthwave, drum and bass): the owner wants a song of it here and there, never
   * the backbone of a ride, so the planner uses at most one per section.
   */
  supplement?: true;
  /** Day the uploads were last checked, ISO date. */
  verified: string;
}

export interface SoundtrackCatalog {
  v: 1;
  tracks: CatalogTrack[];
}

/**
 * Cadence the catalog's roles assume for a song: songs from `HALF_FROM_BPM` up are ridden two beats
 * per pedal stroke (BPM / 2), slower songs one beat per stroke (BPM = RPM). The planner still
 * matches every tempo by `matchBpm` (exact, half and double time); this only fixes the roles.
 */
export const HALF_FROM_BPM = 125;
/** Owner's rule: a song ridden at this cadence or faster is for sprints and intervals only. */
export const ROLE_SPRINT_RPM = 105;

export function catalogRpm(bpm: number): number {
  return bpm >= HALF_FROM_BPM ? bpm / 2 : bpm;
}

/** Song lengths the catalog accepts, seconds. */
export const TRACK_MIN_SEC = 60;
export const TRACK_MAX_SEC = 900;
/** Uploads per song: at least two (one may be blocked), at most the queue schema's six. */
export const MIN_UPLOADS = 2;
export const MAX_UPLOADS = 6;

/** Longest energy note, characters. */
export const ENERGY_NOTE_MAX = 120;

const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** No duplicates in a list of labels. */
const distinct = <T>(a: readonly T[]): boolean => new Set(a).size === a.length;

const uploadSchema = z.strictObject({
  id: z.string().regex(YOUTUBE_ID),
  label: z.string().min(1).max(60).optional(),
  offsetSec: z.number().int().min(0).max(600).optional(),
  durationSec: z.number().int().min(TRACK_MIN_SEC).max(TRACK_MAX_SEC),
});

/**
 * One catalog entry. Strict: an unknown key (a Spotify id, a URL, a helper field of the proposal)
 * is an error, so nothing but the schema's metadata can reach the shipped file.
 */
export const catalogTrackSchema = z
  .strictObject({
    id: z.string().regex(SLUG).max(80),
    artist: z.string().trim().min(1).max(120),
    title: z.string().trim().min(1).max(160),
    bpm: z.number().min(BPM_MIN).max(BPM_MAX).optional(),
    durationSec: z.number().int().min(TRACK_MIN_SEC).max(TRACK_MAX_SEC),
    version: z.enum(['extended', 'radio']).optional(),
    startOffsetSec: z.number().int().min(0).max(600).optional(),
    categories: z.array(z.enum(MUSIC_CATEGORIES)).min(1).refine(distinct, 'duplicate category'),
    roles: z.array(z.enum(TRACK_ROLES)).min(1).refine(distinct, 'duplicate role'),
    energy: z.union([z.literal(1), z.literal(2), z.literal(3), z.literal(4), z.literal(5)]),
    groove: z.union([z.literal(1), z.literal(2), z.literal(3)]).optional(),
    mood: z.enum(TRACK_MOODS).optional(),
    tagged: z.literal(2).optional(),
    energyNote: z.string().trim().min(1).max(ENERGY_NOTE_MAX).optional(),
    beat: z.enum(['steady', 'none']),
    clean: z.boolean(),
    traits: z.array(z.enum(TRACK_TRAITS)).min(1).refine(distinct, 'duplicate trait').optional(),
    bpmNote: z.string().min(1).max(160).optional(),
    gem: z.literal(true).optional(),
    pl: z.literal(true).optional(),
    supplement: z.literal(true).optional(),
    verified: z.string().regex(ISO_DATE),
    youtube: z
      .array(uploadSchema)
      .min(MIN_UPLOADS)
      .max(MAX_UPLOADS)
      .refine((ups) => distinct(ups.map((u) => u.id)), 'the same upload twice'),
  })
  .refine((t) => t.beat === 'none' || t.bpm !== undefined, {
    message: 'a song on the beat needs its BPM',
    path: ['bpm'],
  });

export const catalogSchema = z.strictObject({
  v: z.literal(1),
  tracks: z.array(catalogTrackSchema).min(1),
});

/**
 * Problems across entries that the per-entry schema cannot see, as readable lines (empty = fine):
 * duplicate ids, the same song twice (`songKey`), one upload under two songs, and the owner's
 * role rule (a song ridden at `ROLE_SPRINT_RPM` or faster is for intervals only).
 */
/**
 * A song for sprints: it has the intervals role, it is not calm (energy 4 or 5) and it does not
 * start with a long intro (the drop has to come from the first repeat).
 */
export function isSprintTrack(t: Pick<CatalogTrack, 'roles' | 'energy' | 'traits'>): boolean {
  return t.roles.includes('intervals') && t.energy >= 4 && !t.traits?.includes('long-intro');
}

export function catalogProblems(tracks: readonly CatalogTrack[]): string[] {
  const problems: string[] = [];
  const ids = new Set<string>();
  const songs = new Map<string, string>();
  const uploads = new Map<string, string>();
  for (const t of tracks) {
    if (ids.has(t.id)) problems.push(`${t.id}: duplicate id`);
    ids.add(t.id);
    const key = songKey(t);
    const same = songs.get(key);
    if (same !== undefined) problems.push(`${t.id}: same song as ${same}`);
    else songs.set(key, t.id);
    for (const u of t.youtube) {
      const owner = uploads.get(u.id);
      if (owner !== undefined && owner !== t.id) {
        problems.push(`${t.id}: upload ${u.id} also used by ${owner}`);
      } else uploads.set(u.id, t.id);
    }
    const rpm = t.bpm === undefined ? undefined : catalogRpm(t.bpm);
    // The finisher role is a mark on top of the real ones, so it does not count here.
    const real = t.roles.filter((r) => r !== FINISHER_ROLE);
    if (
      rpm !== undefined &&
      rpm >= ROLE_SPRINT_RPM &&
      (real.length !== 1 || real[0] !== 'intervals')
    ) {
      problems.push(`${t.id}: ridden at ${rpm} rpm, so its only role is intervals`);
    }
    if (t.beat === 'none' && t.groove !== undefined) {
      problems.push(`${t.id}: a song without a beat has no groove`);
    }
    if (t.roles.includes(FINISHER_ROLE)) {
      if (real.length === 0) problems.push(`${t.id}: a finisher also needs another role`);
      if (t.energy < 4) problems.push(`${t.id}: a finisher needs energy 4 or 5`);
      if (t.mood !== 'euphoric') problems.push(`${t.id}: a finisher needs the euphoric mood`);
    }
    // Sprint = intervals + energy 4-5 + no long intro. A song that has the intervals role without
    // being one (a ballad ridden at 105 rpm), or a peak song for a warm-up or cool-down, is kept
    // as catalogued but has to say why: the tagging does not change roles, it reports them.
    if (t.energyNote !== undefined && t.tagged === undefined) {
      problems.push(`${t.id}: an energy note needs the tagging revision (tagged: 2)`);
    }
    if (t.tagged === 2 && t.energyNote === undefined) {
      const unfit = t.roles.includes('intervals') && !isSprintTrack(t);
      const hot = t.energy === 5 && (t.roles.includes('warmup') || t.roles.includes('cooldown'));
      if (unfit) problems.push(`${t.id}: intervals role without sprint energy needs an energyNote`);
      if (hot) problems.push(`${t.id}: energy 5 in a warm-up or cool-down needs an energyNote`);
    }
  }
  return problems;
}

/**
 * Validates raw catalog data (the parsed JSON file). Throws with every problem listed, so a broken
 * edit of the data file fails loudly in tests and never ships half-checked.
 */
export function parseCatalog(raw: unknown): SoundtrackCatalog {
  const parsed = catalogSchema.safeParse(raw);
  if (!parsed.success) {
    const lines = parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`);
    throw new Error(`Soundtrack catalog is invalid:\n${lines.join('\n')}`);
  }
  const catalog = parsed.data as SoundtrackCatalog;
  const problems = catalogProblems(catalog.tracks);
  if (problems.length > 0) {
    throw new Error(`Soundtrack catalog is invalid:\n${problems.join('\n')}`);
  }
  return catalog;
}
